class FileHandle extends EventEmitter {
  constructor(fd, flag) {
    super();
    this[kFd] = fd ? fd : -1;
    this[kRefs] = 1;
    this[kClosePromise] = null;
    this[kFlag] = flag;
  }

async stat(options) {
  const fd = this[kFd];
  throwEBADFIfNecessary("fstat", fd);

  try {
    this[kRef]();
    return await fstat(fd, options);
  } finally {
    this[kUnref]();
  }
}

async close() {
  const fd = this[kFd];
  if (fd === -1) {
    return Promise.$resolve();
  }

  if (this[kClosePromise]) {
    return this[kClosePromise];
  }

  if (--this[kRefs] === 0) {
    this[kFd] = -1;
    this[kClosePromise] = PromisePrototypeFinally.$call(close(fd), () => {
      this[kClosePromise] = undefined;
    });
  } else {
    this[kClosePromise] = PromisePrototypeFinally.$call(
      new Promise((resolve, reject) => {
        this[kCloseResolve] = resolve;
        this[kCloseReject] = reject;
      }),
      () => {
        this[kClosePromise] = undefined;
        this[kCloseReject] = undefined;
        this[kCloseResolve] = undefined;
      },
    );
  }

  this.emit("close");
  return this[kClosePromise];

close(throwOnError = false) {
  this.clearQueryCache();
  // Finalize any prepared statements created by db.transaction()
  if (controllers) {
    const controller = controllers.get(this);
    if (controller) {
      controllers.delete(this);
      const seen = new Set();
      for (const ctrl of [controller.default, controller.deferred, controller.immediate, controller.exclusive]) {
        if (!ctrl) continue;
        for (const stmt of [ctrl.begin, ctrl.commit, ctrl.rollback, ctrl.savepoint, ctrl.release, ctrl.rollbackTo]) {
          if (stmt && !seen.has(stmt)) {
            seen.add(stmt);
            stmt.finalize?.();
          }
        }
      }
    }
  }
  this.#hasClosed = true;
  return SQL.close(this.#handle, throwOnError);
}
clearQueryCache() {
  for (let item of this.#cachedQueriesValues) {
    item?.finalize?.();
  }

